package com.example.agentic_ai_platform.marketing.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="mkt_seo_keywords") public class SeoKeyword {
 @Id private UUID id; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(nullable=false,length=255) private String keyword; @Column(name="target_page",length=2048) private String targetPage; @Column(name="current_rank") private Integer currentRank; @Column(name="previous_rank") private Integer previousRank; @Column(name="search_volume") private Integer searchVolume; private Integer difficulty; @Column(nullable=false,length=32) private String intent; @Column(nullable=false,length=24) private String status; @Column(name="meta_title",length=70) private String metaTitle; @Column(name="meta_description",length=170) private String metaDescription; @Column(name="ai_recommendation",columnDefinition="TEXT") private String aiRecommendation; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected SeoKeyword(){}
 public SeoKeyword(UUID id,UUID tenant,com.example.agentic_ai_platform.marketing.dto.SeoKeywordRequest r){this.id=id;tenantId=tenant;keyword=r.keyword().trim();targetPage=r.targetPage();searchVolume=r.searchVolume()!=null?r.searchVolume():1200;difficulty=r.difficulty()!=null?r.difficulty():50;intent=r.intent()!=null?r.intent():"COMMERCIAL";status="TRACKING";currentRank=null;previousRank=null;createdAt=updatedAt=Instant.now();}
 public void sweep(){updatedAt=Instant.now();}
 public void updateRank(Integer newRank){previousRank=currentRank;currentRank=newRank;updatedAt=Instant.now();}
 public void optimize(String title,String description,String recommendation){metaTitle=title;metaDescription=description;aiRecommendation=recommendation;updatedAt=Instant.now();}
 public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getKeyword(){return keyword;} public String getTargetPage(){return targetPage;} public Integer getCurrentRank(){return currentRank;} public Integer getPreviousRank(){return previousRank;} public Integer getSearchVolume(){return searchVolume;} public Integer getDifficulty(){return difficulty;} public String getIntent(){return intent;} public String getStatus(){return status;} public String getMetaTitle(){return metaTitle;} public String getMetaDescription(){return metaDescription;} public String getAiRecommendation(){return aiRecommendation;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}
}
